/*
 * Yagr берёт цвета фона, сетки и осей из своих CSS-переменных (--yagr-*).
 * Привязываем их к семантическим токенам Gravity UI: так график сам следует
 * за светлой, тёмной и контрастными темами. Две класса в селекторе перебивают
 * `.yagr_theme_*` из index.css Yagr независимо от порядка подключения.
 */
.cpu-load-chart.yagr {
    --yagr-font-family: var(--g-font-family-sans);
    --yagr-background: var(--g-color-base-background);
    --yagr-grid: var(--g-color-line-generic);
    --yagr-axis-stroke: var(--g-color-text-secondary);
    --yagr-title-color: var(--g-color-text-primary);

    position: relative;
    width: 100%;
    height: 100%;
    /* Не даём canvas распирать flex/grid-контейнер — график сжимается вместе с ним. */
    min-width: 0;
    min-height: 0;
    overflow: hidden;
}

/* Тултип Yagr рендерится в document.body и наследует тему от .g-root на body. */
.yagr-tooltip.cpu-load-chart__tooltip {
    font-family: var(--g-text-body-font-family);
    color: var(--g-color-text-primary);
    background-color: var(--g-color-base-float);
    border-radius: var(--g-border-radius-m);
    box-shadow:
        0 0 0 1px var(--g-color-line-generic),
        0 8px 20px 0 var(--g-color-sfx-shadow);
}

